function mat(c, extra) { return new THREE.MeshLambertMaterial(Object.assign({ color: c }, extra || {})); }
scene.add(new THREE.AmbientLight(0xffffff, 0.85));
const sun = new THREE.DirectionalLight(0xffffff, 0.9); sun.position.set(3, 6, 5); scene.add(sun);

// ── Sample tube & sample ────────────────────────────────────────────────
const tubeGrp = new THREE.Group();
const glass = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 4.2, 32, 1, true),
  new THREE.MeshPhongMaterial({ color: 0xbfe3f2, transparent: true, opacity: 0.3, side: THREE.DoubleSide }));
const glassCap = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 12, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glass.material);
glassCap.position.y = -2.1;
const rimT = new THREE.Mesh(new THREE.TorusGeometry(0.18, 0.015, 8, 32), mat(0x9cc4d4)); rimT.rotation.x = Math.PI / 2; rimT.position.y = 2.1;
const rimB = rimT.clone(); rimB.position.y = -2.1;
const sample = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 2.7, 24), mat(0xf2a93b)); sample.position.y = -0.45;
