// ── Coil helix ──────────────────────────────────────────────────────────
class Helix extends THREE.Curve {
  getPoint(t) {
    const turns = 10, a = t * Math.PI * 2 * turns;
    return new THREE.Vector3(0.34 * Math.cos(a), -0.7 + 1.4 * t, 0.34 * Math.sin(a));
