// ── Cables ──────────────────────────────────────────────────────────────
function cable(pts, color) {
  const path = new THREE.CurvePath();
  for (let i = 0; i < pts.length - 1; i++) path.add(new THREE.LineCurve3(pts[i], pts[i + 1]));
  const geo = new THREE.TubeGeometry(path, 64, 0.035, 8);
