}
const v = (x, y, z) => new THREE.Vector3(x, y, z);
const cableGenCoil = cable([v(-2.3, -1.7, 0.3), v(-1.55, -1.7, 0.3), v(-1.55, -1.05, 0.3), v(-0.36, -1.05, 0.3)], 0x35b24a);
