const cableDetMon = cable([v(2.85, -1.2, 0.15), v(2.85, 0.9, 0.1), v(3.0, 0.9, 0.0), v(3.0, 1.35, 0.0)], 0x2b83c5);

// ── RF generator ────────────────────────────────────────────────────────
