const genBox = new THREE.Mesh(new THREE.BoxGeometry(1.7, 1.0, 1.0), mat(0xd8c9a3)); genGrp.add(genBox);
const readout = new THREE.Mesh(new THREE.PlaneGeometry(0.72, 0.34), mat(0x1c2e22)); readout.position.set(0.32, 0.18, 0.505); genGrp.add(readout);
