// spectrum: baseline + peaks
const baseLine = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.015, 0.005), mat(0xd62828));
baseLine.position.set(0, -0.35, 0.06); monGrp.add(baseLine);
const peakDefs = [[-0.55, 0.12], [-0.4, 0.22], [-0.25, 0.16], [0.25, 0.62], [0.42, 0.18]]; // x, height
const peaks = [];
const peakRes = [8.40, null, null, 9.56, 10.60]; // 4th (tallest) ↔ 9.56; use 11.50 for 5th visually
