addLabel('<b>S</b>', v(-1.15, 0, 0.62), { fontSize: '20px' });
addLabel('<b>N</b>', v(1.15, 0, 0.62), { fontSize: '20px' });
addLabel('Radiofrequency<br>generator', v(-3.3, -0.85, 0.4), { fontSize: '13px' });
addLabel('9.56', v(-2.78, -1.9, 0.75), { fontSize: '13px', color: '#7fe08a', background: '#1c2e22' });
