  { obj: coil, cables: [cableCoilDet] },
  { obj: detBox, cables: [cableDetMon] },
  { obj: bezel, cables: [] },
];
let pulseT = -1, pulseIdx = -1;
pathComps.forEach((c, i) => {
  registerInteractive(c.obj, {
    title: PATH[i], tooltip: PATH[i],
