<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// Element spec (one primitive each):
// glass tube      → CylinderGeometry(0.18,0.18,4.2) + hemisphere cap, pale blue transparent
// sample column   → CylinderGeometry(0.12,0.12,2.8) orange, centered y=0 so it spans the coil
// rf coil         → TubeGeometry along helix r=0.34, y∈[-0.7,0.7], 10 turns, green
// collars         → 2× CylinderGeometry(0.30,0.30,0.35) blue at y=±0.85
// magnet poles    → 2× CylinderGeometry(0.68,0.68,0.85) rotated to X axis at x=±1.05
// spin markers    → 16 small spheres in sample, emissive pulse at resonance
// generator       → Box 1.7×1.0×1.0 beige + knobs/buttons/readout at (-3.1,-2.1,0.2)
// detector        → Box 1.0×1.4×0.8 charcoal + dials/buttons at (2.9,-2.0,0.1)
// monitor         → bezel box + screen plane + stand at (4.4,1.6,-0.2), red spectrum lines
// cables          → TubeGeometry paths, green (gen→coil) and blue (coil→det, det→monitor)

function mat(c, extra) { return new THREE.MeshLambertMaterial(Object.assign({ color: c }, extra || {})); }
scene.add(new THREE.AmbientLight(0xffffff, 0.85));
const sun = new THREE.DirectionalLight(0xffffff, 0.9); sun.position.set(3, 6, 5); scene.add(sun);

// ── Sample tube & sample ────────────────────────────────────────────────
const tubeGrp = new THREE.Group();
const glass = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 4.2, 32, 1, true),
  new THREE.MeshPhongMaterial({ color: 0xbfe3f2, transparent: true, opacity: 0.3, side: THREE.DoubleSide }));
const glassCap = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 12, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glass.material);
glassCap.position.y = -2.1;
const rimT = new THREE.Mesh(new THREE.TorusGeometry(0.18, 0.015, 8, 32), mat(0x9cc4d4)); rimT.rotation.x = Math.PI / 2; rimT.position.y = 2.1;
const rimB = rimT.clone(); rimB.position.y = -2.1;
// Sample column spans the whole coil region (and beyond), as in the source.
const sample = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 2.8, 24), mat(0xf2a93b));
sample.position.y = 0;
const sampleCap = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 8, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), sample.material);
sampleCap.position.y = -1.4;
tubeGrp.add(glass, glassCap, rimT, rimB, sample, sampleCap);
scene.add(tubeGrp);

// ── Coil helix ──────────────────────────────────────────────────────────
class Helix extends THREE.Curve {
  getPoint(t) {
    const turns = 10, a = t * Math.PI * 2 * turns;
    return new THREE.Vector3(0.34 * Math.cos(a), -0.7 + 1.4 * t, 0.34 * Math.sin(a));
  }
}
const coil = new THREE.Mesh(new THREE.TubeGeometry(new Helix(), 320, 0.045, 8), mat(0x2fae4e));
scene.add(coil);
const collarGeo = new THREE.CylinderGeometry(0.30, 0.30, 0.35, 24);
const collarTop = new THREE.Mesh(collarGeo, mat(0x2b83c5)); collarTop.position.y = 0.85;
const collarBot = new THREE.Mesh(collarGeo, mat(0x2b83c5)); collarBot.position.y = -0.85;
scene.add(collarTop, collarBot);

// ── Magnet poles (larger, closer to coil, per source proportions) ───────
const poleGeo = new THREE.CylinderGeometry(0.68, 0.68, 0.85, 32);
function makePole(x) {
  const p = new THREE.Mesh(poleGeo, mat(0xc9ced4));
  p.rotation.z = Math.PI / 2; p.position.set(x, 0, 0); scene.add(p); return p;
}
const poleS = makePole(-1.05), poleN = makePole(1.05);

// ── Nuclear spin markers ────────────────────────────────────────────────
const RESONANCES = [8.40, 9.56, 10.60, 11.50], TOL = 0.08;
const spins = [];
for (let i = 0; i < 16; i++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.035, 10, 8),
    new THREE.MeshLambertMaterial({ color: 0x8a5a10, emissive: 0x000000 }));
  const r = 0.07 * Math.sqrt(Math.random()), a = Math.random() * Math.PI * 2;
  s.position.set(r * Math.cos(a), -1.25 + Math.random() * 2.5, r * Math.sin(a));
  s.userData.res = RESONANCES[i % 4];
  scene.add(s); spins.push(s);
}

// ── Cables ──────────────────────────────────────────────────────────────
function cable(pts, color) {
  const path = new THREE.CurvePath();
  for (let i = 0; i < pts.length - 1; i++) path.add(new THREE.LineCurve3(pts[i], pts[i + 1]));
  const geo = new THREE.TubeGeometry(path, 64, 0.035, 8);
  const m = new THREE.Mesh(geo, mat(color, { emissive: 0x000000 }));
  scene.add(m); return m;
}
const v = (x, y, z) => new THREE.Vector3(x, y, z);
const cableGenCoil = cable([v(-2.3, -1.7, 0.3), v(-1.55, -1.7, 0.3), v(-1.55, -1.05, 0.3), v(-0.36, -1.05, 0.3)], 0x35b24a);
const cableCoilDet = cable([v(0.36, -0.9, 0.3), v(1.0, -0.9, 0.3), v(1.0, -1.55, 0.25), v(2.65, -1.55, 0.25)], 0x2b83c5);
const cableDetMon = cable([v(3.15, -1.3, 0.15), v(3.15, 1.0, 0.1), v(3.7, 1.0, 0.0), v(3.7, 1.45, 0.0)], 0x2b83c5);

// ── RF generator ────────────────────────────────────────────────────────
const genGrp = new THREE.Group(); genGrp.position.set(-3.1, -2.1, 0.2);
const genBox = new THREE.Mesh(new THREE.BoxGeometry(1.7, 1.0, 1.0), mat(0xd8c9a3)); genGrp.add(genBox);
const readout = new THREE.Mesh(new THREE.PlaneGeometry(0.72, 0.34), mat(0x1c2e22)); readout.position.set(0.32, 0.18, 0.505); genGrp.add(readout);
[[-0.62, 0.28], [-0.62, 0.0]].forEach(([x, y]) => {
  const k = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.06, 16), mat(0x333333));
  k.rotation.x = Math.PI / 2; k.position.set(x, y, 0.53); genGrp.add(k);
});
[[-0.62, -0.32, 0xc23b22], [-0.32, -0.32, 0x333333], [-0.06, -0.32, 0x333333], [0.2, -0.32, 0xc23b22]].forEach(([x, y, c]) => {
  const b = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, 0.05), mat(c)); b.position.set(x, y, 0.53); genGrp.add(b);
});
[[-0.45, 0.28, 0x2fae4e], [-0.28, 0.28, 0x2b83c5], [-0.11, 0.28, 0xd62828]].forEach(([x, y, c]) => {
  const l = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.04, 10), mat(c));
  l.rotation.x = Math.PI / 2; l.position.set(x, y, 0.52); genGrp.add(l);
});
scene.add(genGrp);

// ── Detector & amplifier (moved further right of the coil) ──────────────
const detGrp = new THREE.Group(); detGrp.position.set(2.9, -2.0, 0.1);
const detBox = new THREE.Mesh(new THREE.BoxGeometry(1.0, 1.4, 0.8), mat(0x3a3f44)); detGrp.add(detBox);
[[0.2, 0.28], [-0.2, -0.05]].forEach(([x, y]) => {
  const dial = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.11, 0.07, 18), mat(0xb9bec4));
  dial.rotation.x = Math.PI / 2; dial.position.set(x, y, 0.43); detGrp.add(dial);
});
[[-0.22, -0.45, 0x35b24a], [0.22, -0.45, 0xc23b22]].forEach(([x, y, c]) => {
  const pb = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.08, 18), mat(c));
  pb.rotation.x = Math.PI / 2; pb.position.set(x, y, 0.43); detGrp.add(pb);
});
scene.add(detGrp);

// ── Monitor (further up-right to match source spacing) ──────────────────
const monGrp = new THREE.Group(); monGrp.position.set(4.4, 1.6, -0.2); monGrp.rotation.y = -0.35;
const bezel = new THREE.Mesh(new THREE.BoxGeometry(2.0, 1.35, 0.09), mat(0x2b2f33)); monGrp.add(bezel);
const screenM = new THREE.Mesh(new THREE.PlaneGeometry(1.85, 1.2), mat(0xa9d6e8)); screenM.position.z = 0.05; monGrp.add(screenM);
const stand = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.28, 0.35, 16), mat(0x2b2f33)); stand.position.y = -0.85; monGrp.add(stand);
const baseLine = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.015, 0.005), mat(0xd62828));
baseLine.position.set(0, -0.35, 0.06); monGrp.add(baseLine);
const peakDefs = [[-0.55, 0.12], [-0.4, 0.22], [-0.25, 0.16], [0.25, 0.62], [0.42, 0.18]];
const peaks = [];
peakDefs.forEach(([x, h], i) => {
  const p = new THREE.Mesh(new THREE.BoxGeometry(0.03, h, 0.006),
    new THREE.MeshLambertMaterial({ color: 0xd62828, emissive: 0x000000 }));
  p.position.set(x, -0.35 + h / 2, 0.06);
  p.userData.res = i === 0 ? 8.40 : i === 3 ? 9.56 : i === 4 ? 11.50 : 10.60;
  monGrp.add(p); peaks.push(p);
});
scene.add(monGrp);

// ── Camera ──────────────────────────────────────────────────────────────
setCameraView({ projection: 'perspective', azimuthDeg: 72, elevationDeg: 14, rollDeg: 0, heightFraction: 0.72, distanceScale: 1.0 });

// ── Labels ──────────────────────────────────────────────────────────────
addLabel('Sample in tube', v(-1.15, 1.55, 0), { fontSize: '14px' });
const leader = new THREE.Mesh(new THREE.TubeGeometry(new THREE.LineCurve3(v(-0.72, 1.45, 0), v(-0.1, 1.15, 0)), 1, 0.01, 6), mat(0x333333));
scene.add(leader);
addLabel('<b>S</b>', v(-1.05, 0, 0.7), { fontSize: '20px' });
addLabel('<b>N</b>', v(1.05, 0, 0.7), { fontSize: '20px' });
addLabel('Radiofrequency<br>generator', v(-3.3, -0.85, 0.4), { fontSize: '13px' });
addLabel('9.56', v(-2.78, -1.9, 0.75), { fontSize: '13px', color: '#7fe08a', background: '#1c2e22' });
addLabel('Detector and<br>amplifier', v(3.8, -1.35, 0.5), { fontSize: '13px' });

// ── Resonance state ─────────────────────────────────────────────────────
let B0 = 9.56;
function resonant(tol) { return RESONANCES.filter(r => Math.abs(B0 - r) < (tol || TOL)); }
const b0Val = document.getElementById('b0Val');
function applyB0(val) {
  B0 = val; b0Val.textContent = val.toFixed(2);
  const res = resonant();
  spins.forEach(s => {
    const on = res.includes(s.userData.res);
    s.material.emissive.setHex(on ? 0xffd24a : 0x000000);
  });
  peaks.forEach(p => {
    const on = res.includes(p.userData.res);
    p.material.emissive.setHex(on ? 0x881111 : 0x000000);
    p.material.color.setHex(on ? 0xff4040 : 0xd62828);
    p.scale.set(on ? 2.2 : 1, on ? 1.12 : 1, 1);
  });
  updateNarration();
}
const slider = document.getElementById('fieldStrength');
slider.addEventListener('input', () => applyB0(parseFloat(slider.value)));

// ── Click signal path ───────────────────────────────────────────────────
const PATH = ['Radiofrequency generator', 'rf coil & sample', 'Detector & amplifier', 'Monitor (spectrum)'];
const pathComps = [
  { obj: genBox, cables: [cableGenCoil] },
  { obj: coil, cables: [cableCoilDet] },
  { obj: detBox, cables: [cableDetMon] },
  { obj: bezel, cables: [] },
];
let pulseT = -1, pulseIdx = -1;
pathComps.forEach((c, i) => {
  registerInteractive(c.obj, {
    title: PATH[i], tooltip: PATH[i],
    body: `Signal path: ${PATH.slice(0, i + 1).join(' → ')}. ` +
      ['The rf generator irradiates the sample at a fixed frequency (readout 9.56).',
        'The coil delivers rf energy to the nuclei; when B0 matches, spins absorb and re-emit.',
        'The detector amplifies the tiny induced signal.',
        'Each resonance appears as one sharp peak on the monitor.'][i],
    onClick: () => { pulseIdx = i; pulseT = 0; }
  });
});
const origEmis = pathComps.map(c => c.obj.material.emissive ? c.obj.material.emissive.getHex() : 0);

// ── Demo steps (goToStep) ───────────────────────────────────────────────
const STEPS = [
  { title: 'Off resonance', B0: 8.0, text: 'At B0 = 8.00 the fixed rf does not match any nuclear transition, so the sample stays quiet and the monitor shows only the red baseline with unemphasized peaks.' },
  { title: 'Resonance at the readout value', B0: 9.56, text: 'At B0 = 9.56 the nuclei matching the generator frequency flash in the sample and the corresponding monitor peak is emphasized, linking absorption to a spectral line.' },
  { title: 'Sweep to another resonance', B0: 11.5, text: 'Increasing B0 toward 11.50 moves resonance to a different set of nuclei; the first peak relaxes while a later peak becomes highlighted.' },
];
let stepIdx = 1, narr = '';
function goToStep(i) {
  stepIdx = i; narr = STEPS[i].text;
  slider.value = STEPS[i].B0;
  applyB0(STEPS[i].B0);
  [0, 1, 2].forEach(j => document.getElementById('step' + j).classList.toggle('active', j === i));
}
[0, 1, 2].forEach(i => document.getElementById('step' + i).addEventListener('click', () => goToStep(i)));
function updateNarration() {
  const el = document.getElementById('narration');
  if (el) el.textContent = narr;
}
goToStep(1);
window.goToStep = goToStep;

// ── Animation: spin pulsing + signal path pulse ─────────────────────────
const clock = new THREE.Clock();
let _lastT = 0;
(function extraAnimate() {
  requestAnimationFrame(extraAnimate);
  const t = clock.getElapsedTime();
  const dt = Math.min(0.1, t - _lastT); _lastT = t;
  const res = resonant();
  spins.forEach(s => {
    if (res.includes(s.userData.res)) {
      const k = 0.5 + 0.5 * Math.sin(t * 8);
      s.material.emissive.setRGB(k, k * 0.8, k * 0.2);
      s.scale.setScalar(1 + 0.4 * k);
    } else s.scale.setScalar(1);
  });
  peaks.forEach(p => {
    if (res.includes(p.userData.res)) {
      const k = 0.5 + 0.5 * Math.sin(t * 6);
      p.material.emissive.setRGB(0.5 + 0.4 * k, 0.05, 0.05);
    }
  });
  if (pulseT >= 0) {
    pulseT += dt;
    const c = pathComps[pulseIdx];
    const on = Math.sin(pulseT * 10) > 0;
    if (c.obj.material.emissive) c.obj.material.emissive.setHex(on ? 0x3355aa : origEmis[pulseIdx]);
    c.cables.forEach(cb => cb.material.emissive.setHex(on ? 0x224466 : 0x000000));
    if (pulseT > 2.4) {
      if (c.obj.material.emissive) c.obj.material.emissive.setHex(origEmis[pulseIdx]);
      c.cables.forEach(cb => cb.material.emissive.setHex(0x000000));
      pulseT = -1;
    }
  }
})();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

